import fs from 'node:fs';
import { pathToFileURL } from 'node:url';

const TOKEN = process.env.GH_TOKEN;
const ORG = process.env.ORG || 'ThanhNguyxnOrg';
const API = process.env.GITHUB_API_URL || 'https://api.github.com';
export const MANAGED_MARKER = '# Managed by ThanhNguyxnAgent Auto-Onboarding. Do not edit this file manually.';

export function isEligibleRepository(repo, organization = ORG, ignoredRepositories = []) {
  const owner = String(repo?.owner?.login || repo?.full_name?.split('/')[0] || '');
  return Boolean(
    repo &&
    owner.toLowerCase() === String(organization).toLowerCase() &&
    repo.archived !== true &&
    repo.fork !== true &&
    typeof repo.name === 'string' &&
    !ignoredRepositories.includes(repo.name) &&
    typeof repo.default_branch === 'string' &&
    repo.default_branch.length > 0
  );
}

function decodeExistingContent(existing) {
  if (!existing || typeof existing.content !== 'string') return '';
  if (existing.encoding === 'base64') {
    return Buffer.from(existing.content.replace(/\s/g, ''), 'base64').toString('utf8');
  }
  return existing.content;
}

export function decideWorkflowWrite(existing, desiredContent) {
  if (!existing) return 'create';
  const currentContent = decodeExistingContent(existing);
  if (currentContent === desiredContent) return 'unchanged';
  if (currentContent.startsWith(MANAGED_MARKER)) return 'update';
  return 'conflict';
}

export function loadWorkflowTemplates() {
  return [
    {
      path: '.github/workflows/agent-pr-signal.yml',
      content: fs.readFileSync(new URL('../templates/agent-pr-signal.yml', import.meta.url), 'utf8')
    },
    {
      path: '.github/workflows/agent-pr-worker.yml',
      content: fs.readFileSync(new URL('../templates/agent-pr-worker.yml', import.meta.url), 'utf8')
    }
  ];
}

function createClient(token, fetchImpl) {
  async function request(path, options = {}) {
    const response = await fetchImpl(API + path, {
      method: options.method || 'GET',
      headers: {
        Authorization: 'Bearer ' + token,
        Accept: 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2022-11-28',
        ...(options.headers || {})
      },
      body: options.body === undefined ? undefined : JSON.stringify(options.body)
    });
    const raw = await response.text();
    let data = null;
    if (raw) {
      try { data = JSON.parse(raw); }
      catch { data = raw; }
    }
    if (!response.ok) {
      const error = new Error((data && data.message) || response.statusText || 'GitHub API request failed');
      error.status = response.status;
      error.path = path;
      throw error;
    }
    return data;
  }

  async function listAll(path) {
    const items = [];
    for (let page = 1; page <= 50; page += 1) {
      const separator = path.includes('?') ? '&' : '?';
      const batch = await request(path + separator + 'per_page=100&page=' + page);
      if (!Array.isArray(batch)) throw new Error('Expected an array from ' + path);
      items.push(...batch);
      if (batch.length < 100) return items;
    }
    throw new Error('Pagination limit reached while listing ' + path);
  }

  return { request, listAll };
}

function encodedPath(path) {
  return path.split('/').map(segment => encodeURIComponent(segment)).join('/');
}

export function normalizeTargetRepository(value, organization = ORG) {
  const fullName = String(value || '').trim();
  const match = /^([A-Za-z0-9_.-]+)\/([A-Za-z0-9_.-]+)$/.exec(fullName);
  if (!match) throw new Error('TARGET_REPOSITORY must be an owner/repository pair');
  if (match[1] === '.' || match[1] === '..' || match[2] === '.' || match[2] === '..') {
    throw new Error('TARGET_REPOSITORY must be an owner/repository pair');
  }
  if (match[1].toLowerCase() !== String(organization).toLowerCase()) {
    throw new Error('TARGET_REPOSITORY is outside the configured organization');
  }
  return match[1] + '/' + match[2];
}

export function assertOnboardingSuccess(summary) {
  const failed = Number(summary?.failed || 0);
  const conflicts = Number(summary?.conflicts || 0);
  if (failed > 0) {
    throw new Error('Auto-onboarding failed for ' + failed + ' managed workflow write(s)');
  }
  if (conflicts > 0) {
    throw new Error('Auto-onboarding found ' + conflicts + ' repository workflow conflict(s); user-owned files were left untouched');
  }
}

export async function onboardRepositories({
  token = TOKEN,
  organization = ORG,
  fetchImpl = fetch,
  workflows = loadWorkflowTemplates(),
  ignoredRepositories = ['.github'],
  targetRepository = process.env.TARGET_REPOSITORY,
  log = console
} = {}) {
  if (!token) throw new Error('GH_TOKEN is required');
  const { request, listAll } = createClient(token, fetchImpl);
  const repositories = targetRepository
    ? [await request('/repos/' + encodedPath(normalizeTargetRepository(targetRepository, organization)))]
    : await listAll('/orgs/' + encodeURIComponent(organization) + '/repos?type=all');
  const eligible = repositories.filter(repo => isEligibleRepository(repo, organization, ignoredRepositories));
  const summary = { repositories: eligible.length, created: 0, updated: 0, unchanged: 0, conflicts: 0, failed: 0, skipped: repositories.length - eligible.length };

  log.log('[onboard] checking ' + eligible.length + ' active repositories for Agent event workflows');

  for (const repo of eligible) {
    for (const workflow of workflows) {
      const fullName = repo.full_name;
      const filePath = encodedPath(workflow.path);
      const contentsPath = '/repos/' + fullName + '/contents/' + filePath;
      try {
        let existing = null;
        try {
          existing = await request(contentsPath + '?ref=' + encodeURIComponent(repo.default_branch));
        } catch (error) {
          if (error.status !== 404) throw error;
        }

        const action = decideWorkflowWrite(existing, workflow.content);
        if (action === 'unchanged') {
          summary.unchanged += 1;
          continue;
        }
        if (action === 'conflict') {
          summary.conflicts += 1;
          log.warn('[onboard-conflict] ' + fullName + ':' + workflow.path + ' already exists and is not Agent-managed; leaving it untouched');
          continue;
        }

        const body = {
          message: 'chore: onboard ThanhNguyxnAgent PR event workflow [skip ci]',
          content: Buffer.from(workflow.content, 'utf8').toString('base64'),
          branch: repo.default_branch
        };
        if (action === 'update') body.sha = existing.sha;
        await request(contentsPath, { method: 'PUT', body });
        summary[action === 'create' ? 'created' : 'updated'] += 1;
        log.log('[onboard-' + action + '] ' + fullName + ':' + workflow.path);
      } catch (error) {
        summary.failed += 1;
        log.warn('[onboard-error] ' + fullName + ':' + workflow.path + ' ' + error.message);
      }
    }
  }

  log.log('[onboard-summary] ' + JSON.stringify(summary));
  return summary;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  onboardRepositories().then(summary => {
    assertOnboardingSuccess(summary);
  }).catch(error => {
    console.error('[onboard-fatal]', error);
    process.exitCode = 1;
  });
}
